/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { EditableSourcecodeComponent } from './editable-sourcecode.component';

/** Editor de Monaco falso: su valor y el aviso de cambios. */
class FakeMonacoEditor {
  value: string;
  listener?: () => void;
  constructor(
    readonly element: HTMLElement,
    readonly options: any,
  ) {
    this.value = options.value ?? '';
  }
  getValue() {
    return this.value;
  }
  setValue(value: string) {
    this.value = value;
  }
  onDidChangeModelContent(listener: () => void) {
    this.listener = listener;
  }
}

const settle = () => new Promise((resolve) => setTimeout(resolve));

describe('EditableSourcecodeComponent', () => {
  const statics = EditableSourcecodeComponent as any;
  let editors: FakeMonacoEditor[];
  let amd: jasmine.Spy & { config: jasmine.Spy };
  let appended: HTMLScriptElement[];

  const create = (inputs: Record<string, unknown> = {}) => {
    const fixture = TestBed.createComponent(EditableSourcecodeComponent);
    Object.entries(inputs).forEach(([name, value]) => fixture.componentRef.setInput(name, value));
    fixture.detectChanges();
    return fixture;
  };

  beforeEach(() => {
    statics.monacoLoaded = false;
    statics.monacoLoadingPromise = null;
    delete (window as any).require;
    editors = [];
    // Loader AMD falso: "carga" el editor al momento
    amd = Object.assign(
      jasmine.createSpy('require').and.callFake((_modules: string[], done: () => void) => done()),
      { config: jasmine.createSpy('config') },
    );
    (window as any).monaco = {
      editor: {
        create: (element: HTMLElement, options: any) => {
          const editor = new FakeMonacoEditor(element, options);
          editors.push(editor);
          return editor;
        },
      },
    };
    appended = [];
    const append = document.body.appendChild.bind(document.body);
    spyOn(document.body, 'appendChild').and.callFake(<T extends Node>(node: T): T => {
      if (node instanceof HTMLScriptElement) {
        appended.push(node);
        // Al cargar el loader queda el `require` AMD en window
        setTimeout(() => {
          (window as any).require = amd;
          node.onload?.(new Event('load'));
        });
        return node;
      }
      return append(node);
    });
    TestBed.configureTestingModule({
      imports: [EditableSourcecodeComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
  });

  afterEach(() => {
    TestBed.resetTestingModule();
    ['monaco', 'require', 'monacoAmdRequire', 'MonacoEnvironment'].forEach((name) => delete (window as any)[name]);
    statics.monacoLoaded = false;
    statics.monacoLoadingPromise = null;
  });

  it('loads the AMD loader of its assets and creates the editor with its options', async () => {
    const fixture = create({ language: 'json', theme: 'vs' });
    fixture.componentInstance.writeValue('{}');
    await settle();
    await settle();

    expect(appended[0].src).toMatch(/\/assets\/monaco\/vs\/loader\.js$/);
    expect(amd.config).toHaveBeenCalledWith({ paths: { vs: '/assets/monaco/vs' } });
    expect(amd).toHaveBeenCalledWith(['vs/editor/editor.main'], jasmine.any(Function));
    expect(editors[0].element).toBe(fixture.componentInstance.editorContainer()!.nativeElement);
    expect(editors[0].options).toEqual(
      jasmine.objectContaining({ language: 'json', theme: 'vs', automaticLayout: true }),
    );
    expect(statics.monacoLoaded).toBeTrue();
  });

  it('reuses the AMD loader already in the page and the editor already loaded', async () => {
    (window as any).require = amd;
    create();
    await settle();
    expect(appended).toEqual([]);

    create();
    await settle();
    expect(amd).toHaveBeenCalledTimes(1);
    expect(editors.length).toBe(2);
  });

  it('shares the loading in progress', () => {
    const fixture = create();
    const pending = statics.monacoLoadingPromise;

    expect((fixture.componentInstance as any).loadMonaco()).toBe(pending);
  });

  it('writes the editor content on each change', async () => {
    const fixture = create();
    const changes: (string | null)[] = [];
    fixture.componentInstance.registerOnChange((value: string | null) => changes.push(value));
    await settle();
    await settle();

    editors[0].value = 'let a = 1;';
    editors[0].listener!();

    expect(changes).toEqual(['let a = 1;']);
  });

  it('shows in the editor a value written from outside', async () => {
    const fixture = create();
    await settle();
    await settle();

    fixture.componentInstance.writeValue('changed');
    fixture.detectChanges();

    expect(editors[0].value).toBe('changed');
  });

  it('gives the worker of each language', async () => {
    create();
    await settle();
    await settle();
    const env = (window as any).MonacoEnvironment;

    expect(env.getWorkerUrl('', 'json')).toContain('worker=vs/language/json/jsonWorker');
    expect(env.getWorkerUrl('', 'typescript')).toContain('worker=vs/language/typescript/tsWorker');
    expect(env.getWorkerUrl('', 'markdown')).toContain('worker=vs/editor/editorWorker');
    expect(env.getWorkerUrl.call({ assetsPath: '/other' }, '', 'css')).toContain('/other/base/worker/workerMain.js');
  });

  it('warns when the editor container is not there', async () => {
    (window as any).require = amd;
    const alert = spyOn(window, 'alert');
    const fixture = create({ visible: false });
    await settle();

    expect(alert).toHaveBeenCalled();
    expect(fixture.componentInstance.editorContainer()).toBeUndefined();
  });
});
